}

public void shiverCamera(ViewportEvent.ComputeCameraAngles event)
{
    LivingEntity entity = Minecraft.getInstance().player;
    if (!this.test(entity)) return;

    if (!Minecraft.getInstance().isPaused() && ConfigSettings.DISTORTION_EFFECTS.get())
    {
        double effect = this.getEffectFactor(entity);
        double tickTime = entity.tickCount + event.getPartialTick();
        float shiverIntensity = (float) CSMath.blend(0, (Math.sin(tickTime / 10) + 1) * 0.03f + 0.01f, effect, 0, 1);
        shiverIntensity *= ConfigSettings.SHIVER_INTENSITY.get();
        // Multiply the effect for lower framerates
        shiverIntensity *= Minecraft.getInstance().getDeltaFrameTime() * 10;
        // Rotate camera
        float shiverRotation = (float) (Math.sin(tickTime * 2.5) * shiverIntensity);
        entity.setYRot(entity.getYRot() + shiverRotation);
    }
}

public Side getSide()
{   return Side.CLIENT;
}

public void onRenderBlur(RenderLevelEvent.Post event)
{
    LivingEntity player = Minecraft.getInstance().player;
    if (!this.test(player)) return;

    double effect = this.getEffectFactor(player);
    float blurMultiplier = ConfigSettings.HEATSTROKE_BLUR_AMOUNT.get().floatValue();
    if (blurMultiplier == 0) return;
    PostProcessShaderManager shaderManager = PostProcessShaderManager.getInstance();

    if (ConfigSettings.DISTORTION_EFFECTS.get())
    {
        float blur = (float) CSMath.blend(0, 12, effect, 0, 1) * blurMultiplier;
        if (!shaderManager.hasEffect("heat_blur"))
        {   shaderManager.loadEffect("heat_blur", PostProcessShaderManager.BLOBS);
        }
        Uniform blurRadius = shaderManager.getPostPasses("heat_blur").get(0).getEffect().getUniform("Radius");
        if (blurRadius != null)
        {   blurRadius.set(blur);
        }
    }
    else if (shaderManager.hasEffect("heat_blur"))
    {   shaderManager.closeEffect("heat_blur");
    }

    shaderManager.process(event.getPartialTick());
}

public Side getSide()
{   return Side.CLIENT;
}

package com.momosoftworks.coldsweat.client.renderer;

import com.google.gson.JsonSyntaxException;
import com.mojang.blaze3d.pipeline.RenderTarget;
import com.momosoftworks.coldsweat.ColdSweat;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.PostChain;
import net.minecraft.client.renderer.PostPass;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.resources.ResourceManager;
import net.minecraftforge.fml.util.ObfuscationReflectionHelper;
import org.joml.Matrix4f;

import java.io.IOException;
import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class PostProcessShaderManager implements AutoCloseable
{
    private static final PostProcessShaderManager INSTANCE = new PostProcessShaderManager(
            Minecraft.getInstance().getMainRenderTarget(),
            Minecraft.getInstance().getResourceManager());

    private static final Map<String, PostChain> ACTIVE_EFFECTS = new HashMap<>();
    private final RenderTarget mainTarget;
    private final ResourceManager resourceManager;
    private boolean screenSizeUpdated = false;

    public static final ResourceLocation BLOBS = new ResourceLocation("minecraft", "shaders/post/blobs2.json");

    public PostProcessShaderManager(RenderTarget mainTarget, ResourceManager resourceManager)
    {
        this.mainTarget = mainTarget;
        this.resourceManager = resourceManager;
    }

    public static PostProcessShaderManager getInstance()
    {   return INSTANCE;
    }

    public void loadEffect(String id, ResourceLocation shaderLocation)
    {
        try
        {
            // Create new PostChain for this effect
            PostChain postChain = new PostChain(
                    Minecraft.getInstance().getTextureManager(),
                    resourceManager,
                    mainTarget,
                    shaderLocation
            );

            // Store it in our active effects
            if (ACTIVE_EFFECTS.put(id, postChain) != null)
            {
                // If we're replacing an existing effect, close the old one
                closeEffect(id);
            }

        }
        catch (IOException | JsonSyntaxException e)
        {   ColdSweat.LOGGER.error("Failed to load shader effect: " + id, e);
        }
    }

    public void closeEffect(String id)
    {
        PostChain chain = ACTIVE_EFFECTS.remove(id);
        if (chain != null)
        {
            chain.close();
        }
    }

    public void process(float partialTicks)
    {
        // Process all active effects
        for (PostChain chain : ACTIVE_EFFECTS.values())
        {
            if (getPostPasses(chain).stream().anyMatch(pass -> getOrthoMatrix(pass) == null))
            {   chain.resize(mainTarget.width, mainTarget.height);
            }
            chain.process(partialTicks);
        }
    }

    public void resize(int width, int height)
    {
        // Resize all active effects
        for (PostChain chain : ACTIVE_EFFECTS.values())
        {
            chain.resize(width, height);
        }
    }

    public boolean hasEffect(String id)
    {   return ACTIVE_EFFECTS.containsKey(id);
    }

    public PostChain getEffect(String id)
    {   return ACTIVE_EFFECTS.get(id);
    }

    private static final Field POST_PASSES = ObfuscationReflectionHelper.findField(PostChain.class, "f_110009_");
    private static final Field ORTHO_MATRIX = ObfuscationReflectionHelper.findField(PostPass.class, "f_110059_");
    static
    {   POST_PASSES.setAccessible(true);
        ORTHO_MATRIX.setAccessible(true);
    }

    public List<PostPass> getPostPasses(String effectId)
    {
        PostChain chain = ACTIVE_EFFECTS.get(effectId);
        if (chain == null)
        {   return List.of();
        }
        try
        {  return (List<PostPass>) POST_PASSES.get(chain);
        }
        catch (Exception e)
        {
            ColdSweat.LOGGER.error("Failed to get post passes for effect: " + effectId, e);
            return List.of();
        }
    }

    public static List<PostPass> getPostPasses(PostChain chain)
    {
        try
        {  return (List<PostPass>) POST_PASSES.get(chain);
        }
        catch (Exception e)
        {
            ColdSweat.LOGGER.error("Failed to get post passes for effect: " + chain, e);
            return List.of();
        }
    }

    public static Matrix4f getOrthoMatrix(PostPass pass)
    {
        try
        {  return (Matrix4f) ORTHO_MATRIX.get(pass);
        }
        catch (Exception e)
        {
            ColdSweat.LOGGER.error("Failed to get ortho matrix for pass: " + pass, e);
            return new Matrix4f();
        }
    }

    @Override
    public void close()
    {
        // Clean up all effects
        for (PostChain chain : ACTIVE_EFFECTS.values())
        {
            chain.close();
        }
        ACTIVE_EFFECTS.clear();
    }
}

package com.momosoftworks.coldsweat.api.event.vanilla;

import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraftforge.eventbus.api.Event;

public class RenderLevelEvent extends Event
{
    PoseStack poseStack;
    float partialTick;

    public RenderLevelEvent(PoseStack poseStack, float partialTick)
    {
        this.poseStack = poseStack;
        this.partialTick = partialTick;
    }

    public PoseStack getPoseStack()
    {   return poseStack;
    }

    public float getPartialTick()
    {   return partialTick;
    }

    /**
     * Fired before any level rendering is done in {@link net.minecraft.client.renderer.GameRenderer#renderLevel(float, long, PoseStack)}.<br>
     * This event is not {@link net.minecraftforge.eventbus.api.Cancelable}.
     */
    public static class Pre extends RenderLevelEvent
    {
        public Pre(PoseStack poseStack, float partialTick)
        {   super(poseStack, partialTick);
        }
    }

    /**
     * Fired after the level is rendered in {@link net.minecraft.client.renderer.GameRenderer#renderLevel(float, long, PoseStack)}.<br>
     */
    public static class Post extends RenderLevelEvent
    {
        public Post(PoseStack poseStack, float partialTick)
        {   super(poseStack, partialTick);
        }
    }
}

private void beforeLevelRender(float partialTick, long finishTimeNano, PoseStack poseStack, CallbackInfo ci)
{   MinecraftForge.EVENT_BUS.post(new RenderLevelEvent.Pre(poseStack, partialTick));
}

private void afterLevelRender(float partialTick, long finishTimeNano, PoseStack poseStack, CallbackInfo ci)
{   MinecraftForge.EVENT_BUS.post(new RenderLevelEvent.Post(poseStack, partialTick));
}

protected boolean test(LivingEntity entity)
{
    return entity != null
        && !entity.isSpectator()
        && !(entity instanceof Player player && player.isCreative())
        && this.bounds().test(Math.round((float) CSMath.clamp(this.getTemperature(entity), -100, 100)));
}

protected double getTemperature(LivingEntity entity)
{   return entity.level().isClientSide ? Overlays.BLEND_BODY_TEMP : Temperature.get(entity, Temperature.Trait.BODY);
}

public double getEffectFactor(LivingEntity entity)
{
    if (EntityTempManager.isImmuneToTemperature(entity)) return 0;
    double temperature = this.getTemperature(entity);
    double minTemp = this.bounds().min();
    double maxTemp = this.bounds().max();
    double resistance = EntityTempManager.getResistance(temperature, entity);
    temperature = CSMath.blend(temperature, minTemp, resistance, 0, 1);
    return CSMath.blend(0, 1, temperature, minTemp, maxTemp);
}

public static boolean isImmuneToTemperature(LivingEntity player)
{   return player == null || !player.isAlive() || isPeacefulMode(player) || player.hasEffect(ModEffects.GRACE);
}

public static boolean isPeacefulMode(LivingEntity entity)
{   return entity.level().getDifficulty() == Difficulty.PEACEFUL && ConfigSettings.USE_PEACEFUL_MODE.get();
}

public static double getColdResistance(LivingEntity entity)
{   return entity.hasEffect(ModEffects.ICE_RESISTANCE) && ConfigSettings.ICE_RESISTANCE_ENABLED.get() ? 1
         : Temperature.get(entity, Trait.COLD_RESISTANCE);
}

public static double getHeatResistance(LivingEntity player)
{
    return player.hasEffect(MobEffects.FIRE_RESISTANCE) && ConfigSettings.FIRE_RESISTANCE_ENABLED.get() ? 1
         : Temperature.get(player, Trait.HEAT_RESISTANCE);
}

public static double getResistance(double temperature, LivingEntity player)
{   return temperature < 0 ? getColdResistance(player) : getHeatResistance(player);
}

public static void addTempEffects(LivingEvent.LivingTickEvent event)
{
    LivingEntity living = event.getEntity();
    if (living.tickCount % 20 == 0)
    {
        EntityTempManager.getTemperatureCap(living).ifPresent(cap ->
        {
            TempEffectsData effectsData = ConfigHelper.getFirstOrNull(ConfigSettings.ENTITY_TEMP_EFFECTS, living.getType(), data -> data.test(living));
            if (effectsData == null) return;

            List<TempEffectType<?>> addedEffects = new ArrayList<>();
            // Add temp effects
            effectsData.effects().forEach(holder ->
            {
                TempEffectType effectType = holder.effect();
                // Add effect
                cap.addTempEffect(effectType.create(effectType, holder.range()), living.level().isClientSide);
                // Mark effect as added
                addedEffects.add(effectType);
            });
            // Remove effects that are not applicable to the entity
            cap.getTempEffects().keySet().stream().filter(type -> !addedEffects.contains(type)).forEach(cap::removeTempEffect);
        });
    }
}

public static void clearTempEffects(EntityLeaveLevelEvent event)
{
    if (event.getEntity() instanceof LivingEntity living)
    {   EntityTempManager.getTemperatureCap(living).ifPresent(ITemperatureCap::clearTempEffects);
    }
}

public void removeTempEffect(TempEffectType<?> effect)
{
    this.tempEffects.computeIfPresent(effect, (type, e) ->
    {
        MinecraftForge.EVENT_BUS.unregister(e);
        return null;
    });
}

public void clearTempEffects()
{   this.tempEffects.values().forEach(MinecraftForge.EVENT_BUS::unregister);
    this.tempEffects.clear();
}

